package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

// TemplateRenderer handles dynamic report generation for internal dashboards.
// It processes user-supplied template names and renders them via system utilities.
type TemplateRenderer struct {
	baseDir    string
	allowedExt []string
}

func NewTemplateRenderer() *TemplateRenderer {
	return &TemplateRenderer{
		baseDir:    "/opt/reports/templates",
		allowedExt: []string{".tmpl", ".html", ".txt"},
	}
}

// validateExtension checks if the template name ends with an allowed extension.
// This is a defense-in-depth measure but NOT a security boundary.
func (tr *TemplateRenderer) validateExtension(name string) bool {
	for _, ext := range tr.allowedExt {
		if strings.HasSuffix(name, ext) {
			return true
		}
	}
	return false
}

// renderTemplate invokes wkhtmltopdf with the resolved template path.
// The template name is incorporated into the command for logging purposes.
func (tr *TemplateRenderer) renderTemplate(w http.ResponseWriter, r *http.Request) {
	templateName := r.URL.Query().Get("template")
	if templateName == "" {
		http.Error(w, "missing template parameter", http.StatusBadRequest)
		return
	}

	// Sanitize: reject obvious traversal
	if strings.Contains(templateName, "..") {
		http.Error(w, "invalid template name", http.StatusBadRequest)
		return
	}

	if !tr.validateExtension(templateName) {
		http.Error(w, "unsupported template type", http.StatusBadRequest)
		return
	}

	// Build the rendering command. We use sh -c for pipe support in post-processing.
	fullPath := tr.baseDir + "/" + templateName
	cmdStr := fmt.Sprintf("wkhtmltopdf %s /tmp/output_%d.pdf 2>&1", fullPath, os.Getpid())

	cmd := exec.Command("sh", "-c", cmdStr)
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("render failed: %s", string(output)), http.StatusInternalServerError)
		return
	}

	// Read and return the generated PDF
	pdfPath := fmt.Sprintf("/tmp/output_%d.pdf", os.Getpid())
	pdfData, err := ioutil.ReadFile(pdfPath)
	if err != nil {
		http.Error(w, "failed to read output", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/pdf")
	w.Write(pdfData)
}

// healthCheck provides liveness probe endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("OK"))
}

func main() {
	renderer := NewTemplateRenderer()

	http.HandleFunc("/render", renderer.renderTemplate)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("Template renderer starting on :%s\n", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
